/** Authored pre-present chapters. Times are relative to the festival, not a new calendar. */
export const ORIGINS=[
 {id:'sable-reed',location:50000,hero:0,title:'Before the Last Delivery',era:'Three years before the festival',days:-1095,region:'Cinderfall',chapter:1,core:'earth',places:['home','town'],
 opening:'The house has not learned to be quiet yet. Sable’s mother is teaching him to carry a tuning reed without gripping it shut. Outside, the first public loudspeaker is being tested.',
 witness:'MARA: Your mother promised Rook a reed. She also promised she would rest. Help me keep at least one of those promises.\nSABLE: Which one am I delivering?\nMARA: Ask her before you decide.',
 clue:'A reed speaks when its narrow end can move. The loudspeaker clamps it at both ends. Someone has mistaken keeping a voice for keeping it alive.',
 repair:['Free the reed; let the sound fade naturally.','Build a removable sleeve; keep a private copy.'],repairText:['The note fades. His mother laughs at the sudden, ordinary quiet.','The sleeve holds one phrase. She writes her name on the case herself.'],
 threat:'A clay scavenger has nested under the relay. Its shell is packed with discarded speaker wire.',peace:'Unwind the wire and leave the relay unpowered.',
 dilemma:'MOTHER: If anyone hears this years from now, I want them to know I meant to leave it. Who should keep the case?',
 choices:['Entrust the case to the family.','Let the workshop keep it under a signed loan.'],
 consequences:['Mara keeps a family reed shelf; its remedies remain freely available.','Rook keeps a lending bench; its spare conductors remain freely available.'],effects:['family-remedies','workshop-conductors'],
 ending:'The errand ends before dusk. Three years will pass before the case leaves this house again. The important thing inside it is permission.',present:'MARA: You asked her what she wanted. I remember. Whatever happens today, keep asking.',item:'tonic'},
 {id:'iona-lowbank',location:50002,hero:1,title:'The Waterline',era:'Two years before the festival',days:-730,region:'Lowbank',chapter:9,core:'mend',places:['lowbank_shelter','refuge'],
 opening:'Lowbank is still a neighbourhood, not a memorial. Iona has six dry blankets, a borrowed clinic key, and a river gauge whose numbers have been painted over.',
 witness:'DARA: The district office calls it a seasonal rise.\nIONA: Then they can come down and explain that to the beds. Help me move them upstairs.',
 clue:'The new gauge measures from the raised embankment. The old nail marks measure from people’s doorsteps. The lower marks predict which homes flood first.',
 repair:['Restore the doorstep gauge for everyone to read.','Run a bell rope from the gauge to the shelter.'],repairText:['Families chalk their own thresholds beside the gauge.','The bell can be rung from the water without leaving the rope.'],
 threat:'A siltback guards the plank bridge. Broken flood boards cling to its natural armour.',peace:'Float a spare plank downstream and lead it away.',
 dilemma:'DARA: We can keep the medical stores here, or send them upriver with the next boat. Neither place has enough.',
 choices:['Keep a public neighbourhood clinic.','Establish travelling relief stores.'],consequences:['A Lowbank clinic keeps a rest station open.','A relief supply shelf serves travellers passing through Lowbank.'],effects:['lowbank-clinic','lowbank-relief'],
 ending:'Iona leaves a key with someone who lives here. A shelter is not saved because a visitor promises to return; it is saved because its neighbours can open the door.',present:'DARA: The water took the old sign. We kept the key. There is still a place here for anyone who needs to lie down.',item:'ether'},
 {id:'rook-regulator',location:50004,hero:2,title:'A Machine for Winter',era:'Eighteen months before the festival',days:-548,region:'Cinderfall workshop',chapter:1,core:'flame',places:['workshop','town'],
 opening:'Before the carriage carries prisoners, its regulator is a heating contract. Rook has been paid half. The workers who need the heat have paid all of it.',
 witness:'ROOK: Why does a heater need a voice plate?\nFOREMAN: So the night shift can send instructions.\nROOK: Then why is the microphone on the intake side?',
 clue:'The intake returns sound upstream when the valve is sealed. A manual release breaks that loop. The contract drawings omit it.',
 repair:['Fit a manual release outside the casing.','Make the voice plate removable without tools.'],repairText:['Any worker can now dump the pressure.','The plate slides free. A machine can be stopped without breaking it.'],
 threat:'An ember crawler has fused scrap over the test furnace. Its borrowed casing traps the heat.',peace:'Vent the cold line and give the crawler a cooler route.',
 dilemma:'The foreman offers the final payment if Rook signs the drawings as complete. The workshop’s coal bill lies under the contract.',
 choices:['Publish the release drawings to the workers.','Keep a duplicate plate and the unsigned contract.'],consequences:['The workshop opens a public repair bench.','The workshop keeps a parts drawer and evidence of the contract.'],effects:['public-bench','contract-drawer'],
 ending:'Rook does not yet know whose voice will enter the machine. He knows enough to leave a way to stop it. That small refusal will matter when Sable arrives.',present:'ROOK: I left a way into that casing. I wish I had asked harder questions before it left the bench.',item:'ether'},
 {id:'brass-rail',location:50006,hero:3,title:'The Unfinished Platform',era:'One year before the festival',days:-365,region:'Rail quarter',chapter:2,core:'ward',places:['station','platform'],
 opening:'The rail quarter has a timetable but no public platform. Brass is ordered to keep people off the tracks while the official entrance stays locked.',
 witness:'PORTER: They built the stairs for inspectors. We carry the injured up the ballast.\nBRASS: Bring the tools. I will hold the gate.',
 clue:'The signal current travels through the gate lock. A separate ground lets the signal work while the gate stays open.',
 repair:['Ground the signal independently of the gate.','Fit a hand-cranked release beside the stairs.'],repairText:['The railway can signal without imprisoning its passengers.','The handle is low enough to reach from a stretcher.'],
 threat:'A railback wears loose brake shoes as armour and is blocking the only usable crossing.',peace:'Move the maintenance trolley to draw it onto a siding.',
 dilemma:'PORTER: The inspectors will call this an unauthorised entrance. What shall we put on the board?',
 choices:['Mark a public passenger crossing.','Mark a protected relief platform.'],consequences:['The rail quarter preserves a public supply crossing.','The rail quarter preserves a relief rest platform.'],effects:['rail-crossing','rail-relief'],
 ending:'Brass signs the board with a name instead of a rank. The first passengers do not salute. They ask when the next train is due.',present:'PORTER: Still open. Still unofficial, according to the paperwork. Sit down if you have been walking.',item:'tonic'},
 {id:'riven-tide',location:50008,hero:4,title:'The Third Tide Mark',era:'Nine months before the festival',days:-274,region:'River settlements',chapter:3,core:'tide',places:['river','bridge'],
 opening:'The upstream charter promises equal water. The downstream cups are empty. Riven arrives to audit a sluice and finds children counting tide marks instead of hours.',
 witness:'KEEPER: They release our share at high tide. It runs backwards.\nRIVEN: That is not a share. That is a signature on an empty page.',
 clue:'At the third exposed tide mark, the river can push through both side channels. The central gate must wait until the channels are open.',
 repair:['Open the side channels before the central sluice.','Fit a visible tide latch that prevents early release.'],repairText:['Clear water reaches both banks before the current turns.','The latch can be checked from either village.'],
 threat:'A brine grazer has armoured itself in gate fragments; it nests where fresh water meets salt.',peace:'Open the empty salt channel and let the grazer follow the brine.',
 dilemma:'KEEPER: The charter needs one keeper. The water needs more than one pair of eyes.',
 choices:['Give both settlements a gate key.','Publish the tide schedule at the shared ferry.'],consequences:['A shared gate house keeps restorative water available.','The ferry keeps a travellers’ supply shelf and a public tide record.'],effects:['shared-water','ferry-record'],
 ending:'Riven leaves two keys where the charter allowed one. The first argument is about who should make the tea. It is a better argument.',present:'KEEPER: Same tide, two keys. If one bank goes quiet, the other checks the gate.',item:'ether'},
 {id:'mira-archive',location:50010,hero:5,title:'Names in the Margin',era:'Six months before the festival',days:-183,region:'Witness archive',chapter:5,core:'gale',places:['archive','office'],
 opening:'Mira is hired to catalogue voices. The register counts recordings; the scraps in the drawer count people. The totals do not agree.',
 witness:'CLERK: A corrected entry has to overwrite the original.\nMIRA: Then how do you prove it was corrected?\nCLERK: You do not. That is why I kept the scraps.',
 clue:'The clay remembers pressure beneath the latest inscription. Side light reveals the old names without erasing the new ones.',
 repair:['Read the tablets with a movable side lamp.','Make reversible clay rubbings before the next audit.'],repairText:['Two hands become visible on the same line.','The copies show the corrections as well as the names.'],
 threat:'A paper moth has layered its wings with discarded index cards. It is eating the only uncensored register.',peace:'Offer blank starch sheets and move the register into a sealed case.',
 dilemma:'CLERK: If every name is public, the collectors can find the families. If none are, the families cannot find each other.',
 choices:['Give families sealed copies they can share themselves.','Keep a protected witness desk with a consent ledger.'],consequences:['A family records shelf holds voluntary copies and supplies.','A witness desk offers a safe rest stop under the archive’s roof.'],effects:['family-copies','witness-desk'],
 ending:'Mira leaves the blank space beside each name intact. A person can be missing without becoming an empty place that someone else owns.',present:'CLERK: We still ask before opening a family’s copy. That has made the catalogue slower. Good.',item:'ether'},
 {id:'veyr-storm',location:50012,hero:6,title:'The Mast That Listened',era:'Three months before the festival',days:-91,region:'Storm observatory',chapter:6,core:'shade',places:['storm_anchorage','summit'],
 opening:'The observatory’s new mast can hear across kingdoms. Veyr is sent to align it before the storm season. The first signal is an operator asking whether anyone can hear them.',
 witness:'OPERATOR: The director wants a single clear channel.\nVEYR: And the other stations?\nOPERATOR: We were told they were interference.',
 clue:'The ground conductor must be attached before the vane is raised. Several quiet stations become readable when the mast stops feeding back its own signal.',
 repair:['Ground the mast before raising the vane.','Separate the listening coil from the transmission coil.'],repairText:['The storm passes through the ground instead of the operators.','For the first time the mast can listen while it is silent.'],
 threat:'A storm kite has collected copper weather vanes over its feathers and will not leave the mast.',peace:'Ground a spare vane away from the tower and let it settle there.',
 dilemma:'OPERATOR: We can keep one powerful broadcast, or leave the channel open for weaker stations to answer.',
 choices:['Keep a listening watch with shared silence.','Give independent stations their own reply windows.'],consequences:['A listening shelter keeps the mountain rest station open.','A relay shelf supplies independent mountain travellers.'],effects:['listening-watch','reply-windows'],
 ending:'Veyr records the first silence as part of the log. Later, someone will call it wasted capacity. The operators will call it the moment they heard an answer.',present:'OPERATOR: We leave a little silence between calls. You never know who has finally found the strength to answer.',item:'ether'}
];
// The first objectives name the people, tools and passages actually present.
// This keeps seven lives legible without requiring the player to learn a second menu.
const ORIGIN_GUIDANCE=[
 {guidance:['Speak with Mara about the reed','Inspect the speaker clamp','Clear the relay for the delivery','Ask Mother who should keep the case'],passage:'Take the reed to the relay outside',returnPath:'Return home to Mara and the reed',creature:'wireback scavenger'},
 {guidance:['Help Dara at the flooded shelter','Inspect the doorstep water gauge','Clear the plank bridge','Decide where the medical stores belong'],passage:'Follow the planks to the flooded worksite',returnPath:'Return to Dara and the water gauge',creature:'siltback'},
 {guidance:['Question the foreman about the heater','Inspect the regulator’s voice intake','Clear the test furnace','Decide what to do with the contract'],passage:'Take the service path to the test furnace',returnPath:'Return to the foreman and regulator',creature:'ember crawler'},
 {guidance:['Meet the porter at the locked crossing','Inspect the gate’s signal current','Clear the passenger crossing','Choose the public platform’s purpose'],passage:'Follow the rail to the crossing',returnPath:'Return to the porter and signal gate',creature:'railback'},
 {guidance:['Hear the keeper’s downstream account','Inspect the third tide mark','Clear the shared sluice','Decide who can open the gate'],passage:'Follow the bank to the shared sluice',returnPath:'Return to the keeper and tide marks',creature:'brine grazer'},
 {guidance:['Ask the clerk about the missing names','Read the inscriptions under side light','Protect the uncensored register','Decide how to protect the families’ names'],passage:'Enter the archive’s register wing',returnPath:'Return to the clerk and side lamp',creature:'paper moth'},
 {guidance:['Hear the operator’s interrupted signal','Inspect the mast’s ground conductor','Clear the listening mast','Choose how the quiet stations will answer'],passage:'Climb to the listening mast',returnPath:'Return to the operator and listening coil',creature:'storm kite'}
];
ORIGINS.forEach((origin,index)=>Object.assign(origin,ORIGIN_GUIDANCE[index]));

// These connections belong to the selected traveller. They explain an earlier
// arrival at the festival without assigning Sable's family history to the lead.
const ORIGIN_JOURNEYS=[
 {aim:'Carry the reed without deciding for the person whose voice it holds.',before:'The first public speaker can keep a phrase. Sable must ask his mother what she wants kept, and who may keep it.',
  promise:['Bring the reed case back to Mara, and come home with it.','Bring the reed case back to Mara, and come home with it.'],
  arrival:['Three years later, Mara takes the case from the family shelf. Rook needs the reed for the Festival of Mended Things. Sable has promised to bring the case home before dark.','Three years later, the workshop’s loan is over and the case is back with Mara. Rook asks to borrow the reed for the festival. This time, too, Sable will bring it home.'],
  concern:['Sable follows the copy of his mother’s voice, but Nell’s father and the other prisoners need him now.','Sable cannot call the rescue finished while the people behind his old deliveries are still paying for them.','Sable still wants to hear his mother. He must not make that longing a rule for everyone else.'],
  home:['','',''],
  homecoming:['Sable puts the carrying strap beside the case. For once, he does not reach for the next delivery.','Sable puts the carrying strap beside the case. For once, he does not reach for the next delivery.']},
 {aim:'Give Lowbank a way to ask for help before the water reaches the beds.',before:'Dara and the neighbours need a warning they can read for themselves, and medical stores they can reach without waiting for Iona.',
  promise:['Keep the Lowbank clinic in the hands of the neighbours who use it.','Keep relief stores travelling to the people who cannot reach a clinic.'],
  arrival:['Dara sends Iona to Cinderfall with the clinic’s requests: steady heat, clean water, and a way to call for help. Iona needs Rook to trace the service line.','Dara sends Iona to Cinderfall with the relief boats’ requests. Supplies can travel upriver; unanswered calls cannot. She needs Rook to inspect the service line.'],
  meeting:'Rook is at the festival, waiting for a reed from Mara. Iona comes to Mara’s door as Sable is packing it.\nIONA: I need to speak to the person who can stop a heating line from swallowing our calls.\nSABLE: I’m going to his orchestra. Come with me.\nMARA: There is room at the table while he finds the strap.',
  concern:['Iona needs the service lines to carry a request for care, not take the voice making it.','Iona is here for the patients who still need water, shelter and a way out after the Crown falls.','Iona needs the city’s new lines to reach a warm room with someone able to answer.'],
  home:['IONA: Dara can open the shelter. She cannot make an unanswered line bring medicine. That is why I came.','IONA: We can carry remedies a long way. We cannot be every district’s only way to ask for them.','IONA: A working line is a beginning. There has to be someone at the other end who can say, “I’m coming.”'],
  homecoming:['IONA: Dara kept the key. I’ll go back through her door and ask what the clinic needs next.','IONA: I’ll take the next relief boat. This time the people downstream can tell us what to bring.']},
 {aim:'Leave the heating machine within reach of the people who depend on it.',before:'The workers have paid for winter heat. Rook must find out why its regulator takes voices and keep a way to stop it.',
  promise:['Keep the release drawings where workers can use and change them.','Keep the unsigned contract and removable plate available as evidence.'],
  arrival:['Rook’s release drawings are still on the public bench, but the installed carriage regulator is sealed behind a works lock. He brings a copy to compare after tuning the festival orchestra.','Rook still has the unsigned contract and duplicate voice plate. A sealed carriage now uses the same regulator. He takes the plate with him on the morning of the festival.'],
  meeting:'First he comes for the reed Mara promised to lend him. Sable is ready to carry it.\nROOK: We’ll mend the orchestra. Then I need to look at something the works have put inside my casing.\nSABLE: The contract you wouldn’t sign?\nROOK: The machine they built anyway.\nMARA: Then both of you bring back something you can explain.',
  concern:['Rook’s regulator connects a promise of winter heat to the carriage taking people’s voices. He must open what he helped build.','Rook cannot repair the harm by repairing a machine alone; its records and the people who used it must be heard.','Rook is making controls that people can reach without asking their maker for permission.'],
  home:['ROOK: There was a release in my drawings. I left it to someone else to make sure the workers could reach it.','ROOK: The reactor can keep its heat. Now we have to keep anyone from sealing the controls again.','ROOK: I can leave a machine people can stop. I cannot write the answer they ought to give me.'],
  homecoming:['ROOK: I’ll put the new drawings on the bench beside the old ones. People should be able to see what I got wrong.','ROOK: I’ll keep the contract beside the plate. The repair belongs in the record with the mistake.']},
 {aim:'Keep a railway entrance open to the people the timetable leaves outside.',before:'The porter needs a crossing that works for passengers and stretchers, even when an inspector keeps the official gate shut.',
  promise:['Keep the public crossing open without requiring a rank or a pass.','Keep the relief platform open to the injured and the people carrying them.'],
  arrival:['The porter sends Brass a list of sealed carriages using the public crossing. Their passengers never come down the stairs. Brass follows the loading schedule to Cinderfall.','The porter sends Brass the relief platform’s log. Carriages arrive there, but no patients are handed over. Brass follows the loading schedule to Cinderfall.'],
  meeting:'A regulator’s workshop mark leads him to Rook. At Mara’s door, he finds the courier taking Rook a festival reed.\nBRASS: I need a mechanic who can open a carriage from the outside.\nSABLE: Rook’s at the orchestra. What’s inside it?\nBRASS: That is the question I should have asked before I signed for it.\nMARA: Start by asking it now.',
  concern:['Brass has followed a carriage from the crossing he kept open. He owes its passengers more than an explanation of the timetable.','Brass signed an order that put people on a train. Opening a way out matters more than defending that signature.','Brass needs the new roads to work for people who have no uniform, pass or authority.'],
  home:['BRASS: The porter kept the crossing open. I kept believing the paperwork about what passed through it.','BRASS: A gate can be open on a map and closed to the person standing in front of it. I have been that gate.','BRASS: If someone is waiting outside, we have not finished opening the road.'],
  homecoming:['BRASS: I’m going back to the platform. Nobody should have to trust my uniform to use the crossing.','BRASS: I’m going back to the platform. If the next stretcher arrives without papers, it still gets through.']},
 {aim:'Let both riverbanks see and control the water they were promised.',before:'The keeper’s doorstep marks contradict the charter. Riven must put the flow where people can check it, not behind another signature.',
  promise:['Leave both settlements able to open the shared gate.','Keep the tide record where people crossing the ferry can challenge it.'],
  arrival:['Both gatekeepers send Riven the same report: the side channels are open, but the promised water still fails farther upstream. He follows the service plan to Cinderfall.','The ferry’s public record shows the same missed releases on both banks. Riven brings that record to Cinderfall to compare it with the works’ service plan.'],
  meeting:'The regulator on the plan is Rook’s. At Mara’s table, Sable recognizes the workshop’s address.\nRIVEN: I have a survey that says people are getting water. They are not.\nSABLE: Rook can read that valve drawing. I’m taking him this.\nRIVEN: Then I’ll carry the survey myself. I have sent enough signed pages ahead of me.',
  concern:['Riven follows the missing water upstream; the same service works carry heat and stolen voices.','Riven must let the families harmed by his survey decide what repair can mean.','Riven needs a network whose claims can be checked from both ends of a river.'],
  home:['RIVEN: The figures were neat enough to sign. The people downstream had to live in what the figures left out.','RIVEN: Two people can hold keys and still be kept waiting by the same order. We have to change who can answer it.','RIVEN: A survey ought to begin an argument we can settle at the river. It should not make the river impossible to question.'],
  homecoming:['RIVEN: I’ll go back with the survey. Both keepers get to read it before I put my name on it.','RIVEN: I’ll take the corrected record to the ferry. Leave space underneath it for what the next season teaches us.']},
 {aim:'Recover the people beneath the register without handing their lives to its collectors.',before:'The clerk kept the scraps. Mira can expose how entries were changed while leaving families a choice about who sees their names.',
  promise:['Let families decide when and with whom to share their copies.','Keep the witness desk answerable to the people named in its records.'],
  arrival:['A family lets Mira bring the workshop mark from its copied cylinder to Cinderfall. The name stays in their sealed copy. Rook may be able to identify the carrier.','The witness desk gives Mira permission to trace a cylinder’s workshop mark. She leaves the protected names with the clerk and takes only the mechanical evidence.'],
  meeting:'Rook’s workshop is closed for the festival. Mara knows who is carrying his missing reed.\nMIRA: I need him to read a mark. Not the voice inside it.\nSABLE: He’ll ask what happened to the rest of the page.\nMIRA: Then I’ll tell him whose permission he needs.\nMARA: Good. Walk together. The square is filling up.',
  concern:['Mira follows a copied cylinder from the families’ records to the machinery that treats them as property.','Mira needs the recovered names to help their owners without giving collectors another list of doors.','Mira is helping the city keep an account that witnesses can correct and control.'],
  home:['MIRA: A name on a cylinder tells us who was recorded. It does not tell us who agreed to this.','MIRA: We can return a register and still leave its owners with no say. The desk has to listen as well as keep.','MIRA: The difficult passages stay. So does the space for someone to answer them.'],
  homecoming:['MIRA: I have copies to take back. I’ll knock, and let each family decide whether to open the book.','MIRA: I’ll go back to the desk. We will keep asking before we show a page. Even when asking takes longer.']},
 {aim:'Let the quiet stations answer instead of clearing them from the channel.',before:'The operator has heard people the director calls interference. Veyr can make room for their replies without deciding what they should say.',
  promise:['Keep a listening watch that leaves time for an answer.','Keep independent stations able to use their own reply windows.'],
  arrival:['The listening watch sends Veyr a log of unanswered calls from Cinderfall. The mast can hear them; something below will not return the answer. He follows the line down.','Independent stations send Veyr their reply records. Their windows are open, but Cinderfall keeps transmitting through them. He comes to inspect the lower connection.'],
  meeting:'Rook can read the local regulator. While looking for him, Veyr reaches Mara’s door beside Sable’s last delivery.\nVEYR: I signed the network’s specifications. The operators say it will no longer listen.\nSABLE: And you believe them?\nVEYR: Enough to come down from the mast. Take me to Rook.\nMARA: You can help carry his reed. It does not need a specification.',
  concern:['Veyr follows the operators’ unanswered calls into a network built under his authorization.','Veyr must hear living people instead of making them fit the reply he wanted from a recording.','Veyr needs the network to stop transmitting long enough for someone else to answer.'],
  home:['VEYR: The operators told me what was wrong. I kept looking for a fault in their instruments.','VEYR: I know how to make a voice repeat. I am learning how to stay when it says something I did not expect.','VEYR: The next reply may be quiet. That is no reason to fill the space before it arrives.'],
  homecoming:['VEYR: I owe the listening watch a reply. Not another instruction.','VEYR: I’ll take my turn in a reply window. The other stations can finish first.']}
];
ORIGINS.forEach((origin,index)=>{origin.journey=ORIGIN_JOURNEYS[index];});

export const originById=id=>ORIGINS.find(o=>o.id===id);
export const ORIGIN_SCHEMA='ash-aether.origins/1';
